// Independent, ignored, explicitly synthetic controls; never a provider client.
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFile,writeFile} from "node:fs/promises";
import path from "node:path";
import {fileURLToPath} from "node:url";
import {assessDelivery} from "../../lib/delivery-assessment.ts";
import {recordRiskReview} from "../../lib/risk-reviews.ts";
import {prepareProjectEvaluation,projectQuote,validateProjectCorpus} from "../../scripts/run-project-assessment-evaluation.ts";

const ROOT=fileURLToPath(new URL("../../",import.meta.url)),OUT=path.dirname(fileURLToPath(import.meta.url));
const hash=bytes=>createHash("sha256").update(bytes).digest("hex"),json=async file=>JSON.parse(await readFile(file,"utf8"));
const slots=ids=>Object.fromEntries(Array.from({length:6},(_,i)=>[`c${i+1}`,ids[i]??""]));
const state=q=>({status:q.status,captureId:q.captureId,paymentState:q.proof.paymentState,acceptedAt:q.proof.acceptedAt,acceptedDeliveryId:q.proof.acceptedDeliveryId,paymentOperation:q.proof.paymentOperation,acceptanceEvidence:q.proof.delivery.acceptanceEvidence});
const corpusPath=path.join(ROOT,"scripts/evidence-actions-boundary-corpus-2026-11-06.json"),refsPath=path.join(ROOT,"scripts/evidence-actions-boundary-references-2026-11-06.json");
const cb=await readFile(corpusPath),rb=await readFile(refsPath),refs=JSON.parse(rb),corpus=validateProjectCorpus(JSON.parse(cb));
assert.equal(hash(cb),"b0ed37335770f9de649974cd55ca410911a77e0e9199d2e94501a774ca4f62a3");
assert.equal(hash(rb),"98def261ee50f56ff97f6ccdfb88b7e74e8ba9b126cc4f0c4f3f4baf8f803c51");
const archived=await json(path.join(OUT,"cycle-18-final-implementation.json"));
for(const row of archived.files)assert.equal(hash(await readFile(path.join(ROOT,row.file))),row.sha256);
const replay=await json(path.join(OUT,"cycle-18-final-replay.json")),manifest=await json(path.join(OUT,"retained-replay-inputs.json"));
const quotes=new Map();for(const group of manifest.groups){const c=validateProjectCorpus(await json(group.corpus));for(const p of c.projects)quotes.set(p.id,projectQuote(p));}
const namespaceRows=[];let savedAnnotations=0,rejectedNamespaceRequests=0,rejectedStaleVersionRequests=0,retryChecks=0;
const denied=operation=>{assert.throws(operation);rejectedNamespaceRequests++;};
for(const row of replay.rows){
 const report=row.currentApplication.report,q=structuredClone(quotes.get(row.id));q.proof.delivery.assessment=structuredClone(report);
 q.status="paid";q.captureId="controlled-existing-capture";q.proof.paymentState="captured";q.proof.acceptedAt="2026-11-06T00:00:00.000Z";q.proof.acceptedDeliveryId=q.proof.delivery.id;
 const published=report.risks.length,withheld=report.withheldRisks.entries.length;
 const namespace=withheld?"withheld":"published",count=withheld||published;
 for(let index=0;index<count;index++){
  let current=structuredClone(q);
  for(const role of["buyer","seller"]){
   const input={deliveryId:report.deliveryId,assessmentId:report.id,riskIndex:index,decision:"needs_evidence",reason:"Controlled role and origin check, not a confirmed defect.",...(namespace==="withheld"?{riskOrigin:"withheld"}:{})};
   const before=structuredClone(current),after=recordRiskReview(current,role,input,"2026-11-06T00:00:00.000Z");
   assert.deepEqual(current,before);assert.deepEqual(after.proof.delivery.assessment,report);assert.deepEqual(state(after),state(before));
   assert.equal(after.proof.delivery.riskReviews.at(-1).riskOrigin,namespace==="withheld"?"withheld":undefined);
   assert.equal(after.proof.delivery.riskReviews.at(-1).actorRole,role);savedAnnotations++;
   assert.equal(recordRiskReview(after,role,input,"2026-11-06T00:00:00.000Z"),after);retryChecks++;
   const replaced=structuredClone(after);replaced.proof.delivery.id="controlled-new-delivery";
   assert.throws(()=>recordRiskReview(replaced,role,input));rejectedStaleVersionRequests++;
   assert.throws(()=>recordRiskReview(after,role,{...input,assessmentId:"controlled-stale-assessment"}));rejectedStaleVersionRequests++;
   const opposite={...input};if(namespace==="withheld")delete opposite.riskOrigin;else opposite.riskOrigin="withheld";
   denied(()=>recordRiskReview(current,role,opposite));current=after;
  }
  assert.deepEqual(current.proof.delivery.riskReviews.map(r=>r.actorRole),["buyer","seller"]);
 }
 if(!count)for(const role of["buyer","seller"])for(const origin of[undefined,"withheld"]){const input={deliveryId:report.deliveryId,assessmentId:report.id,riskIndex:0,decision:"needs_evidence",reason:"Controlled absent pool.",...(origin?{riskOrigin:origin}:{})};denied(()=>recordRiskReview(q,role,input));}
 namespaceRows.push({id:row.id,publishedRisks:published,withheldRisks:withheld,roles:count?["buyer","seller"]:[],everyRiskIndexReviewed:count>0,annotationsSaved:count*2,noPoolBothOriginsRejected:count===0});
}

const priorFetch=globalThis.fetch;let externalAttempts=0,interceptedRequests=0;globalThis.fetch=async()=>{externalAttempts++;throw new Error("Controlled batch cannot reach a network.");};
const boundaryRows=[];
try{
 const prepared=await prepareProjectEvaluation(corpus,{corpusText:cb.toString("utf8")});
 const authorDry=await json(path.join(OUT,"eight-boundaries-author-dry-run.json"));
 for(const p of prepared.prepared){
  const ref=refs.cases.find(row=>row.id===p.project.id),dry=authorDry.requestBodies.find(row=>row.id===p.project.id);
  assert.equal(hash(p.body),dry.requestSha256);const quote=projectQuote(p.project),before=structuredClone(quote);let bodyText,providerBody,requests=0;
  const report=await assessDelivery(quote,{DEEPSEEK_API_KEY:"controlled-offline-no-provider"},async(_url,init)=>{
   requests++;interceptedRequests++;assert.equal(String(init.body),p.body);
   const packet=JSON.parse(JSON.parse(String(init.body)).messages[1].content),entries=packet.citationCatalog.entries,selected=[];
   for(const [file,source]of Object.entries(p.project.files).filter(([file])=>file.endsWith(".html"))){
    let chosen;
    if(ref.citationSelection==="whole-file")chosen=entries.filter(e=>e.file===file&&e.start===0&&e.end===source.length);
    else if(ref.citationSelection==="partial-owner")chosen=entries.filter(e=>e.file===file&&e.start%400===0&&e.end===Math.min(e.start+400,source.length));
    else{const start=source.indexOf('<div class="dish">'),end=source.indexOf("</div>",start)+6;assert.ok(start>=0);chosen=entries.filter(e=>e.file===file&&e.start===start&&e.end===end);}
    assert.ok(chosen.length>0);selected.push(...chosen.map(e=>e.id));
   }
   assert.ok(selected.length<=6);const output={catalogId:packet.citationCatalog.catalogId,items:packet.criteria.map(c=>({criterionId:c.id,status:ref.controlledRawStatus,explanation:"Author-fixed controlled answer for a protocol boundary, not an AI inference.",citations:slots(selected)})),risks:[],limitations:["Controlled response only; no external model or website execution."]};
   providerBody={choices:[{finish_reason:"tool_calls",message:{content:null,tool_calls:[{type:"function",function:{name:"submit_source_assessment_v3",arguments:JSON.stringify(output)}}]}}]};bodyText=JSON.stringify(providerBody);return new Response(bodyText,{headers:{"Content-Type":"application/json"}});
  });
  assert.equal(requests,1);assert.deepEqual(quote,before);assert.equal(report.items.length,1);
  const actual=report.items[0].status;
  boundaryRows.push({id:p.project.id,requestSha256:hash(p.body),sourceFiles:Object.entries(p.project.files).map(([file,source])=>({file,sha256:hash(source)})),
   sourceReferenceStatus:ref.sourceReferenceStatus,controlledRawStatus:ref.controlledRawStatus,controlledExpectedApplicationStatus:ref.expectedApplicationStatus,actualApplicationStatus:actual,
   controlledGateMet:actual===ref.expectedApplicationStatus,sourceReferenceAgreement:actual===ref.sourceReferenceStatus,quoteUnchanged:true,providerBodySha256:hash(bodyText),controlledProviderBody:providerBody,applicationReport:report});
 }
}finally{globalThis.fetch=priorFetch;}
assert.equal(externalAttempts,0);
for(const row of archived.files)assert.equal(hash(await readFile(path.join(ROOT,row.file))),row.sha256);
assert.equal(hash(await readFile(corpusPath)),refs.corpusSha256);assert.equal(hash(await readFile(refsPath)),hash(rb));
const report={schema:"pbp-cycle18-independent-controlled-boundaries-and-roles-v1",apiCalls:0,modelCalls:0,networkCalls:0,externalAttempts,interceptedControlledResponses:interceptedRequests,
 corpusSha256:hash(cb),referenceSha256:hash(rb),harnessSha256:hash(await readFile(fileURLToPath(import.meta.url))),providerArchiveSha256:hash(await readFile(path.join(OUT,"cycle-18-final-implementation.json"))),
 namespace:{reports:namespaceRows.length,reportsWithRisks:namespaceRows.filter(r=>r.everyRiskIndexReviewed).length,noPoolReports:namespaceRows.filter(r=>r.noPoolBothOriginsRejected).length,publishedRisks:namespaceRows.reduce((n,r)=>n+r.publishedRisks,0),withheldRisks:namespaceRows.reduce((n,r)=>n+r.withheldRisks,0),roles:["buyer","seller"],savedAnnotations,retryChecks,rejectedNamespaceRequests,rejectedStaleVersionRequests,rows:namespaceRows},
 boundaries:{cases:boundaryRows.length,controlledGatesMet:boundaryRows.filter(r=>r.controlledGateMet).length,sourceReferenceAgreement:boundaryRows.filter(r=>r.sourceReferenceAgreement).length,rows:boundaryRows},
 limits:["All eight responses are authored catalog-selector mocks passed through the real active assessor, not provider/model calls or model performance.","Source-reference agreement remains separate from deliberately conservative controlled gate expectations; references were not edited to improve either count.","Namespace/state controls use local synthetic captured/accepted state fields and no payment action. Valid frozen-acceptance lifecycle is also covered by separate domain tests.","All risk indices were reviewed separately by buyer and seller, with default published versus explicit withheld namespaces; no valid v1 report has both active and quarantined pools.","No root live8 response was read. Source corpora, references and previous artifacts remain unchanged."]};
const target=path.join(OUT,"cycle-18-controlled-boundaries-and-roles.json");await writeFile(target,JSON.stringify(report,null,2)+"\n",{flag:"wx",mode:0o600});
console.log(JSON.stringify({output:target,namespace:report.namespace,controlledCases:report.boundaries.cases,controlledGatesMet:report.boundaries.controlledGatesMet,sourceReferenceAgreement:report.boundaries.sourceReferenceAgreement,apiCalls:0,networkCalls:0}));
